// Async utility library following a pattern: each function returns a Promise,
// accepts an options object, and handles edge cases with specific error types.

function delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

class RetryError extends Error {
    constructor(message, attempts, lastError) {
        super(message);
        this.name = 'RetryError';
        this.attempts = attempts;
        this.lastError = lastError;
    }
}

// Pattern: async utility that wraps a function with specific behavior
async function timeout(fn, ms) {
    return Promise.race([
        fn(),
        new Promise((_, reject) =>
            setTimeout(() => reject(new Error('Timeout')), ms)
        )
    ]);
}

