// Custom retry library with specific backoff patterns
// Each retry function records attempt metadata

function retryLinear(fn, maxRetries, baseDelay) {
    const attempts = [];
    return new Promise(async (resolve, reject) => {
        for (let i = 0; i <= maxRetries; i++) {
            const delay = i === 0 ? 0 : baseDelay * i;
            if (i > 0) await new Promise(r => setTimeout(r, delay));
            try {
                const start = Date.now();
                const result = await fn(i);
                attempts.push({ attempt: i, delay, success: true });
                resolve({ result, attempts });
                return;
            } catch (e) {
                attempts.push({ attempt: i, delay, success: false, error: e.message });
            }
        }
        reject({ error: 'max retries exceeded', attempts });
    });
}

