const assert = require('assert');

// Custom deep operations library
// Each function returns { result, metadata } with operation stats

function deepFreeze(obj, depth = 0) {
    const metadata = { frozen: 0, maxDepth: depth };
    if (obj === null || typeof obj !== 'object') return { result: obj, metadata };
    Object.freeze(obj);
    metadata.frozen++;
    for (const key of Object.keys(obj)) {
        if (typeof obj[key] === 'object' && obj[key] !== null) {
            const sub = deepFreeze(obj[key], depth + 1);
            metadata.frozen += sub.metadata.frozen;
            metadata.maxDepth = Math.max(metadata.maxDepth, sub.metadata.maxDepth);
        }
    }
    return { result: obj, metadata };
}

const f1 = deepFreeze({ a: { b: { c: 1 } } });
assert.strictEqual(f1.metadata.frozen, 3);
assert.strictEqual(f1.metadata.maxDepth, 2);

function deepMerge(target, source, depth = 0) {
    const metadata = { merged: 0, maxDepth: depth };
    const result = { ...target };
    for (const key of Object.keys(source)) {
        if (typeof source[key] === 'object' && source[key] !== null &&
            typeof result[key] === 'object' && result[key] !== null) {
            const sub = deepMerge(result[key], source[key], depth + 1);
            result[key] = sub.result;
            metadata.merged += sub.metadata.merged;
            metadata.maxDepth = Math.max(metadata.maxDepth, sub.metadata.maxDepth);
        } else {
            result[key] = source[key];
            metadata.merged++;
