function decimalEntityEncode(str, safeChars = '') {
    // Encodes everything that is NOT alphanumeric and NOT in safeChars
    // Uses &#DD; decimal numeric character references (NOT named entities)
    let out = '';
    for (const c of str) {
        if (isAlphanumeric(c) || safeChars.includes(c)) {
            out += c;
        } else {
            out += '&#' + c.charCodeAt(0) + ';';
        }
    }
    return out;
}

